export function WorkOsCatalogHarness() {
  const colors = workOsColors('light');
  const [index, setIndex] = useState(0);
  const key = BOARD_KEYS[index] ?? BOARD_KEYS[0]!;
  const Board = Storyboards[key];
  return (
    <View style={{ flex: 1, backgroundColor: colors.canvas }}>
      <View style={{ padding: workOsSpace.md, borderBottomWidth: 1, borderBottomColor: colors.border, flexDirection: 'row', gap: workOsSpace.sm, alignItems: 'center' }}>
        <Pressable onPress={() => setIndex((v) => (v - 1 + BOARD_KEYS.length) % BOARD_KEYS.length)}><Text style={{ color: colors.accent }}>Prev</Text></Pressable>
        <Text style={[workOsType.headline, { color: colors.ink, flex: 1 }]}>{String(key)}</Text>
        <Pressable onPress={() => setIndex((v) => (v + 1) % BOARD_KEYS.length)}><Text style={{ color: colors.accent }}>Next</Text></Pressable>
      </View>
      <View style={{ flex: 1 }}>{Board ? <Board /> : null}</View>
      <ScrollView horizontal style={{ maxHeight: 64, borderTopWidth: 1, borderTopColor: colors.border }} contentContainerStyle={{ padding: workOsSpace.sm, gap: workOsSpace.sm }}>
        {Object.keys(DOCS).slice(0, 20).map((d) => (
          <Text key={d} style={[workOsType.caption, { color: colors.inkMuted, width: 220 }]} numberOfLines={3}>{DOCS[d]}</Text>
        ))}
      </ScrollView>
    </View>
  );
}
